// regra — só é 'enviado' o que o servidor SMTP ACEITOU (nodemailer devolve accepted[] e messageId).
// Não se confia no ramo de saída: quando o Send Email morre ANTES do laço de itens (credencial
// 'smtp' ausente), o n8n 2.37.10 repassa o item de ENTRADA, sem marca de erro, como se fosse
// sucesso (n8n-core workflow-execute.js:1143-1146). A 1ª versão deste fluxo marcou 'enviado'
// um e-mail que nunca saiu. Falha nunca é silêncio: scripts/20_monitor.py:408-435.
const r = $json;
const origem = $('Um por vez').item.json;
const aceitos = Array.isArray(r.accepted) ? r.accepted : [];
if (r.messageId && aceitos.length > 0) {
  return { json: { id: origem.id, enviado: true, erro: null } };
}
let erro;
if (r.error) {
  erro = 'SMTP recusou/falhou: ' + (typeof r.error === 'object' ? (r.error.message || JSON.stringify(r.error)) : r.error);
} else if (Array.isArray(r.rejected) && r.rejected.length) {
  erro = 'SMTP rejeitou os destinatários: ' + r.rejected.join(', ');
} else if (!$env.FOPA_SMTP_CONFIGURADO) {
  erro = "SMTP não configurado: credencial 'smtp' ausente no n8n (SMTP_HOST vazio no docker/.env); "
       + 'o Send Email falhou antes de enviar.';
} else {
  erro = 'Send Email não confirmou o aceite do servidor SMTP (sem accepted/messageId).';
}
if (!origem.para) erro = 'sem destinatário: nenhum admin ativo em usuarios. ' + erro;
return { json: { id: origem.id, enviado: false, erro: erro.slice(0, 1000) } };
